package com.traphouse;

import java.awt.BorderLayout;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.CardLayout;
import javax.swing.*;
import javax.swing.JTabbedPane;
import net.runelite.client.ui.PluginPanel;

final class TrapHouseDashboard extends PluginPanel {
    private final JTabbedPane tabs = new JTabbedPane();
    private int selected;
    private final CardLayout cards = new CardLayout();
    private final JPanel pages = new JPanel(cards);
    private JButton[] navigationButtons;

    TrapHouseDashboard(TrapHousePanel bossPanel, TrapHousePanel skillPanel, int selectedTab) {
        this(bossPanel, skillPanel, selectedTab, null);
    }

    TrapHouseDashboard(TrapHousePanel bossPanel, TrapHousePanel skillPanel, int selectedTab, RankingPanel ranking) {
        setLayout(new BorderLayout());
        if (ranking != null) {
            JPanel header = ClanStyle.column();
            ClanStyle.add(header, ClanStyle.brand());
            JPanel navigation = new JPanel(new GridLayout(0,2,5,5));
            navigation.setAlignmentX(java.awt.Component.LEFT_ALIGNMENT);
            navigation.setOpaque(false);
            String[] names = {"Profile","Ranks","Leaderboard","Achievements","Events","Diary","Competitions","Activity"};
            JComponent[] rankPages = ranking.pages();
            JButton[] buttons = new JButton[names.length];
            navigationButtons=buttons;
            for (int i=0;i<names.length;i++) {
                final int index=i;
                buttons[i]=ClanStyle.button(names[i],()-> {
                    selected=index; cards.show(pages,Integer.toString(index));
                    for(int b=0;b<buttons.length;b++) buttons[b].setBackground(b==index?new java.awt.Color(137,38,53):new java.awt.Color(33,37,46));
                });
                navigation.add(buttons[i]);
                buttons[i].setMargin(new java.awt.Insets(6,1,6,1));buttons[i].setFont(new Font("SansSerif",Font.BOLD,10));
                if(i<rankPages.length&&i!=4)pages.add(rankPages[i],Integer.toString(i));
            }
            JTabbedPane eventTabs = new JTabbedPane();
            eventTabs.setFont(new Font("SansSerif",Font.BOLD,10));
            eventTabs.addTab("Boss event",bossPanel);eventTabs.addTab("Skill event",skillPanel);
            eventTabs.addTab("Clan events",rankPages[4]);
            pages.add(eventTabs,"4");
            pages.add(ranking.racePage(),"6");pages.add(ranking.activityPage(),"7");
            header.add(navigation); add(header,BorderLayout.NORTH);add(pages,BorderLayout.CENTER);
            ranking.navigation(()->buttons[0].doClick(),()->buttons[2].doClick());
            buttons[Math.max(0,Math.min(selectedTab,7))].doClick();
            return;
        }
        tabs.setFont(new Font("SansSerif", Font.BOLD, 11));
        if (ranking != null) {
            tabs.setTabLayoutPolicy(JTabbedPane.SCROLL_TAB_LAYOUT);
            ranking.addTabs(tabs);
        }
        tabs.addTab("Boss event", bossPanel);
        tabs.addTab("Skill event", skillPanel);
        tabs.setToolTipTextAt(ranking == null ? 0 : 3, "Boss of the Week: competition kill gains");
        tabs.setToolTipTextAt(ranking == null ? 1 : 4, "Skill of the Month: competition XP gains");
        tabs.setSelectedIndex(selectedTab);
        add(tabs, BorderLayout.CENTER);
    }

    int selectedTab() { return getComponent(0) == tabs ? tabs.getSelectedIndex() : selected; }

    void showProfile() { if(navigationButtons!=null)navigationButtons[0].doClick(); }
}

package com.traphouse;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.time.Instant;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class TrapHouseEventOverlay extends OverlayPanel {
    private final Client client;
    private final TrapHouseConfig config;
    private final TrapHouseClanPlugin plugin;
    private final PanelComponent bossSection = createSection();
    private final PanelComponent skillSection = createSection();

    @Inject
    TrapHouseEventOverlay(Client client, TrapHouseConfig config, TrapHouseClanPlugin plugin) {
        super(plugin);
        this.client = client;
        this.config = config;
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(230, 0));
        panelComponent.setBackgroundColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
        panelComponent.setGap(new Point(0, 12));
    }

    @Override public Dimension render(Graphics2D graphics) {
        if (!config.showEventOverlay() || (!config.showBossOverlay() && !config.showSkillOverlay())
            || client.getGameState() != GameState.LOGGED_IN) return null;
        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder().text("TRAP HOUSE Events").color(new Color(237, 190, 102)).build());
        if (config.showBossOverlay()) addEvent(false);
        if (config.showSkillOverlay()) addEvent(true);
        return super.render(graphics);
    }

    private static PanelComponent createSection() {
        PanelComponent section = new PanelComponent();
        section.setBackgroundColor(null);
        section.setBorder(new Rectangle());
        section.setGap(new Point(0, 3));
        return section;
    }

    private void addEvent(boolean skill) {
        PanelComponent section = skill ? skillSection : bossSection;
        section.getChildren().clear();
        ClanEvent event = plugin.getEvent(skill);
        String target = event == null ? (plugin.isEventChecked(skill) ? "No active event" : "Loading...") : EventSummary.target(event);
        section.getChildren().add(LineComponent.builder().left(skill ? "SKILL EVENT" : "BOSS EVENT")
            .leftColor(new Color(237, 190, 102)).right(target).build());
        if (event != null) {
            section.getChildren().add(LineComponent.builder().left(EventSummary.timing(event, Instant.now())).leftColor(Color.LIGHT_GRAY).build());
            if (config.showOverlayLeaders()) {
                for (int index = 0; index < Math.min(3, event.scores.size()); index++) {
                    LeaderboardEntry entry = event.scores.get(index);
                    section.getChildren().add(LineComponent.builder().left((index + 1) + ". " + net.runelite.client.util.Text.removeTags(entry.name))
                        .right(String.format(Locale.US, "%,d %s", entry.score, skill ? "XP" : "kills")).build());
                }
            }
        }
        panelComponent.getChildren().add(section);
    }
}

package com.traphouse;

import java.awt.*;
import java.util.Locale;
import java.util.List;
import java.util.Collections;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.LinkBrowser;

public class TrapHousePanel extends PluginPanel {
    private static final String DISCORD_URL = CommunityLinkButton.DISCORD_URL;
    private static final String WEBSITE_URL = CommunityLinkButton.WEBSITE_URL;
    private static final int FIRST_PRIZE = 10_000_000;
    private static final int SECOND_PRIZE = 5_000_000;
    private static final int THIRD_PRIZE = 2_500_000;
    private static final Color WHITE = new Color(239, 241, 246);
    private static final Color MUTED = new Color(143, 151, 167);
    private static final Color RED = new Color(255, 77, 91);
    private static final Color GOLD = new Color(237, 190, 102);
    private final JPanel leaderboardRows = new JPanel();
    private final JLabel leaderboardStatus = wrapped("Connecting to Wise Old Man...", 10, MUTED);
    private final JButton refreshButton = button("Refresh leaderboard", false);
    private final JButton openEventButton = button("Open on Wise Old Man", false);
    private final JLabel personalProgress = wrapped("Log in to see your event progress.", 10, GOLD);
    private ClanEvent currentEvent;
    private String playerName;
    private JPanel leaderboardCard;
    private final JLabel eventHeading = label("BOSS OF THE WEEK", 10, RED);
    private final JLabel eventStatus = label("", 9, MUTED);
    private final JLabel eventTitle = wrapped("Finding current event...", 17, WHITE);
    private final JLabel eventBoss = wrapped("From Wise Old Man", 14, GOLD);
    private final JLabel eventDates = wrapped("", 9, MUTED);
    private final boolean skillEvent;

    TrapHousePanel(TrapHouseConfig config, Runnable refresh) {
        this(config, refresh, false);
    }

    TrapHousePanel(TrapHouseConfig config, Runnable refresh, boolean skillEvent) {
        this.skillEvent = skillEvent;
        setBackground(new Color(15, 17, 22));
        setBorder(new EmptyBorder(12, 10, 16, 10));
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));

        JPanel header = card(true);
        header.add(label("THE CLAN / THE GRIND", 9, new Color(255, 160, 165)));
        gap(header, 9);
        JPanel brand = new JPanel(new BorderLayout(8, 0));
        brand.setOpaque(false);
        brand.setAlignmentX(Component.LEFT_ALIGNMENT);
        JLabel logo = new JLabel(new ImageIcon(ImageUtil.loadImageResource(TrapHousePanel.class, "logo.png")
            .getScaledInstance(56, 56, Image.SCALE_SMOOTH)));
        logo.setToolTipText("TRAP HOUSE clan logo");
        brand.add(logo, BorderLayout.WEST);
        brand.add(label("<html>TRAP<br>HOUSE<span style='color:#ff4d5b'>.</span></html>", 25, WHITE), BorderLayout.CENTER);
        brand.setMaximumSize(new Dimension(Integer.MAX_VALUE, brand.getPreferredSize().height));
        header.add(brand);
        gap(header, 10);
        header.add(label("PvM. Skill. TRAP.", 12, new Color(222, 184, 191)));
        section(header);

        JPanel event = card(false);
        event.add(eventHeading);
        gap(event, 8);
        event.add(eventTitle);
        gap(event, 4);
        event.add(eventStatus);
        gap(event, 14);
        event.add(label(skillEvent ? "FEATURED SKILL" : "YOUR TARGET", 9, MUTED));
        gap(event, 4);
        event.add(eventBoss);
        gap(event, 8);
        event.add(eventDates);
        gap(event, 10);
        openEventButton.setEnabled(false);
        openEventButton.addActionListener(e -> {
            if (currentEvent != null) LinkBrowser.browse("https://wiseoldman.net/competitions/" + currentEvent.id);
        });
        event.add(openEventButton);
        section(event);

        leaderboardCard = card(false);
        leaderboardCard.add(label(skillEvent ? "SKILL XP LEADERBOARD" : "BOSS KILL LEADERBOARD", 10, GOLD));
        gap(leaderboardCard, 5);
        leaderboardCard.add(label("WISE OLD MAN / GROUP 2504", 9, MUTED));
        gap(leaderboardCard, 4);
        leaderboardCard.add(label(skillEvent ? "XP GAINED DURING EVENT" : "KILLS GAINED DURING EVENT", 9, MUTED));
        gap(leaderboardCard, 8);
        leaderboardCard.add(personalProgress);
        gap(leaderboardCard, 14);
        leaderboardRows.setOpaque(false);
        leaderboardRows.setAlignmentX(Component.LEFT_ALIGNMENT);
        leaderboardRows.setLayout(new BoxLayout(leaderboardRows, BoxLayout.Y_AXIS));
        leaderboardCard.add(leaderboardRows);
        gap(leaderboardCard, 10);
        leaderboardCard.add(leaderboardStatus);
        gap(leaderboardCard, 10);
        refreshButton.setToolTipText("Refresh Wise Old Man data (at most once every 30 seconds)");
        refreshButton.addActionListener(e -> refresh.run());
        leaderboardCard.add(refreshButton);
        renderScores(Collections.emptyList(), "Loading scores");
        section(leaderboardCard);
        JPanel prizes = card(false);
        prizes.add(label("THE PRIZE POOL", 10, GOLD));
        gap(prizes, 12);
        prizes.add(prize("01", "FIRST PLACE", FIRST_PRIZE, GOLD));
        gap(prizes, 10);
        prizes.add(prize("02", "SECOND PLACE", SECOND_PRIZE, new Color(185, 197, 215)));
        gap(prizes, 10);
        prizes.add(prize("03", "THIRD PLACE", THIRD_PRIZE, new Color(207, 153, 120)));
        section(prizes);

        add(linkButton("Open Discord", DISCORD_URL, true));
        gap(this, 7);
        add(linkButton("Open Clan Website", WEBSITE_URL, false));
        gap(this, 14);
        add(label("YOUR GRIND. YOUR COMMUNITY.", 9, MUTED));
        gap(this, 4);
        add(label("Auto-refresh / every 5 minutes", 9, MUTED));
        if (skillEvent) eventHeading.setText("SKILL OF THE MONTH");
